def vowel_back(s):
    def shift_char(c, shift, exceptions):
        if c in exceptions:
            return chr(ord(c) - 1)
        new_c = chr((ord(c) - ord('a') + shift) % 26 + ord('a'))
        if new_c in 'code':
            return c
        return new_c

    vowels = 'aeiou'
    result = []
    for c in s:
        if c in vowels:
            result.append(shift_char(c, -5, 'ae'))
        else:
            result.append(shift_char(c, 9, 'cd'))
    return ''.join(result)
